insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-attack-on-titan-trivia',
  'Attack on Titan Trivia: Walls, Titans and the Survey Corps',
  'Attack on Titan: eight questions about the Walls, the Nine Titans, the Survey Corps and how Hajime Isayama''s story ends.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'anime-manga'),
  '[{"id":"q1","question":"Which is the outermost of the three Walls protecting humanity?","options":[{"id":"a","text":"Wall Rose","is_correct":false},{"id":"b","text":"Wall Sina","is_correct":false},{"id":"c","text":"Wall Maria","is_correct":true},{"id":"d","text":"Wall Trost","is_correct":false}],"explanation":"Wall Maria is the outermost; it fell in the year 845 when the Colossal Titan breached the Shiganshina district."},{"id":"q2","question":"Where is a titan''s only weak spot?","options":[{"id":"a","text":"The nape of the neck","is_correct":true},{"id":"b","text":"The eyes","is_correct":false},{"id":"c","text":"The heart","is_correct":false},{"id":"d","text":"The ankles","is_correct":false}],"explanation":"Slicing the nape destroys the human inside; it is the only lethal blow against a titan."},{"id":"q3","question":"What is the emblem of the Survey Corps?","options":[{"id":"a","text":"A unicorn","is_correct":false},{"id":"b","text":"Two crossed roses","is_correct":false},{"id":"c","text":"A royal crown","is_correct":false},{"id":"d","text":"The Wings of Freedom","is_correct":true}],"explanation":"The Wings of Freedom symbolize the Survey Corps; the unicorn belongs to the Military Police and the roses to the Garrison."},{"id":"q4","question":"Which titan does Eren Yeager inherit from his father Grisha?","options":[{"id":"a","text":"The Colossal Titan","is_correct":false},{"id":"b","text":"The Attack Titan","is_correct":true},{"id":"c","text":"The Armored Titan","is_correct":false},{"id":"d","text":"The Beast Titan","is_correct":false}],"explanation":"Grisha passed the Attack Titan to Eren, and with it the Founding Titan he had stolen from the royal family."},{"id":"q5","question":"What title does the series give Levi Ackerman?","options":[{"id":"a","text":"The Titan Slayer","is_correct":false},{"id":"b","text":"The King of the Walls","is_correct":false},{"id":"c","text":"Humanity''s strongest soldier","is_correct":true},{"id":"d","text":"The Spear of Heaven","is_correct":false}],"explanation":"Levi is introduced as humanity''s strongest soldier and serves as a captain in the Survey Corps."},{"id":"q6","question":"Who is revealed to be the Female Titan?","options":[{"id":"a","text":"Mikasa Ackerman","is_correct":false},{"id":"b","text":"Pieck Finger","is_correct":false},{"id":"c","text":"Ymir","is_correct":false},{"id":"d","text":"Annie Leonhart","is_correct":true}],"explanation":"Annie, infiltrated in the Military Police, is unmasked as the Female Titan at the end of the first season."},{"id":"q7","question":"Which titan does Armin Arlert inherit?","options":[{"id":"a","text":"The Colossal Titan","is_correct":true},{"id":"b","text":"The Armored Titan","is_correct":false},{"id":"c","text":"The Female Titan","is_correct":false},{"id":"d","text":"The Jaw Titan","is_correct":false}],"explanation":"Armin devours Bertolt Hoover during the Return to Shiganshina arc and takes the Colossal Titan."},{"id":"q8","question":"In which year did the final episode of the anime air?","options":[{"id":"a","text":"2021","is_correct":false},{"id":"b","text":"2022","is_correct":false},{"id":"c","text":"2025","is_correct":false},{"id":"d","text":"2023","is_correct":true}],"explanation":"The anime ended in November 2023 with the second part of The Final Chapters; the manga had ended in April 2021."}]'::jsonb,
  null,
  array['attack on titan', 'anime', 'manga', 'shonen', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
