values (
  'es-trivia-attack-on-titan',
  'Trivia de Attack on Titan: muros, titanes y la Legión',
  'Attack on Titan: ocho preguntas sobre los muros, los nueve titanes, la Legión de Reconocimiento y el final de la historia de Hajime Isayama.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'anime-manga'),
  '[{"id":"q1","question":"¿Cuál es el muro más externo de los tres que protegen a la humanidad?","options":[{"id":"a","text":"El Muro Rose","is_correct":false},{"id":"b","text":"El Muro Sina","is_correct":false},{"id":"c","text":"El Muro María","is_correct":true},{"id":"d","text":"El Muro Trost","is_correct":false}],"explanation":"El Muro María es el más externo; cayó en el año 845, cuando el Titán Colosal destruyó el distrito de Shiganshina."},{"id":"q2","question":"¿Dónde está el único punto débil de un titán?","options":[{"id":"a","text":"En la nuca","is_correct":true},{"id":"b","text":"En los ojos","is_correct":false},{"id":"c","text":"En el corazón","is_correct":false},{"id":"d","text":"En los tobillos","is_correct":false}],"explanation":"Cortar la nuca destruye al humano que está dentro del titán; es el único golpe letal."},{"id":"q3","question":"¿Qué emblema lleva la Legión de Reconocimiento?","options":[{"id":"a","text":"Un unicornio","is_correct":false},{"id":"b","text":"Dos rosas cruzadas","is_correct":false},{"id":"c","text":"Una corona real","is_correct":false},{"id":"d","text":"Las Alas de la Libertad","is_correct":true}],"explanation":"Las Alas de la Libertad simbolizan a la Legión; el unicornio corresponde a la Policía Militar y las rosas a la Guarnición."},{"id":"q4","question":"¿Qué titán hereda Eren Jaeger de su padre Grisha?","options":[{"id":"a","text":"El Titán Colosal","is_correct":false},{"id":"b","text":"El Titán de Ataque","is_correct":true},{"id":"c","text":"El Titán Acorazado","is_correct":false},{"id":"d","text":"El Titán Bestia","is_correct":false}],"explanation":"Grisha le transmitió a Eren el Titán de Ataque y, con él, el Titán Fundador que le había robado a la familia real."},{"id":"q5","question":"¿Qué título le da la serie a Levi Ackerman?","options":[{"id":"a","text":"El matatitanes","is_correct":false},{"id":"b","text":"El rey de los muros","is_correct":false},{"id":"c","text":"El soldado más fuerte de la humanidad","is_correct":true},{"id":"d","text":"La lanza del cielo","is_correct":false}],"explanation":"Levi es presentado como el soldado más fuerte de la humanidad y capitán de la Legión de Reconocimiento."},{"id":"q6","question":"¿Quién resulta ser el Titán Hembra?","options":[{"id":"a","text":"Mikasa Ackerman","is_correct":false},{"id":"b","text":"Pieck Finger","is_correct":false},{"id":"c","text":"Ymir","is_correct":false},{"id":"d","text":"Annie Leonhart","is_correct":true}],"explanation":"Annie, infiltrada en la Policía Militar, se revela como el Titán Hembra al final de la primera temporada."},{"id":"q7","question":"¿Qué titán hereda Armin Arlert?","options":[{"id":"a","text":"El Titán Colosal","is_correct":true},{"id":"b","text":"El Titán Acorazado","is_correct":false},{"id":"c","text":"El Titán Hembra","is_correct":false},{"id":"d","text":"El Titán Mandíbula","is_correct":false}],"explanation":"Armin devora a Bertolt Hoover en el arco del regreso a Shiganshina y se queda con el Titán Colosal."},{"id":"q8","question":"¿En qué año se emitió el episodio final del anime?","options":[{"id":"a","text":"2021","is_correct":false},{"id":"b","text":"2022","is_correct":false},{"id":"c","text":"2025","is_correct":false},{"id":"d","text":"2023","is_correct":true}],"explanation":"El anime terminó en noviembre de 2023 con la segunda parte de The Final Chapters; el manga había cerrado en abril de 2021."}]'::jsonb,
  null,
  array['attack on titan', 'anime', 'manga', 'shonen', 'trivia']::text[],
  3,
  'published',
