   is_featured, is_ai_generated, published_at)
values (
  'en-demon-slayer-trivia',
  'Demon Slayer Trivia: Breathing Styles and the Hashira',
  'Demon Slayer: eight questions about Tanjiro''s journey, the breathing styles, the Hashira and the demons of Muzan Kibutsuji.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'anime-manga'),
  '[{"id":"q1","question":"Who turned Tanjiro''s sister Nezuko into a demon?","options":[{"id":"a","text":"Akaza","is_correct":false},{"id":"b","text":"Muzan Kibutsuji","is_correct":true},{"id":"c","text":"Rui","is_correct":false},{"id":"d","text":"Doma","is_correct":false}],"explanation":"Muzan, the first demon, attacked the Kamado family and turned Nezuko; he is the series'' main villain."},{"id":"q2","question":"Which breathing style does Tanjiro learn first?","options":[{"id":"a","text":"Thunder Breathing","is_correct":false},{"id":"b","text":"Flame Breathing","is_correct":false},{"id":"c","text":"Wind Breathing","is_correct":false},{"id":"d","text":"Water Breathing","is_correct":true}],"explanation":"He learns Water Breathing from Sakonji Urokodaki; the Hinokami Kagura (Sun Breathing) comes later."},{"id":"q3","question":"Giyu Tomioka is the Hashira of what?","options":[{"id":"a","text":"Water","is_correct":true},{"id":"b","text":"Flame","is_correct":false},{"id":"c","text":"Mist","is_correct":false},{"id":"d","text":"Serpent","is_correct":false}],"explanation":"Giyu is the Water Hashira and the one who sends Tanjiro to train under Urokodaki."},{"id":"q4","question":"Which demon kills Kyojuro Rengoku on the Mugen Train?","options":[{"id":"a","text":"Enmu","is_correct":false},{"id":"b","text":"Gyutaro","is_correct":false},{"id":"c","text":"Akaza","is_correct":true},{"id":"d","text":"Doma","is_correct":false}],"explanation":"Enmu falls on the train, but it is Akaza, Upper Rank Three, who kills the Flame Hashira Rengoku."},{"id":"q5","question":"From which breathing style do all the others derive?","options":[{"id":"a","text":"Moon Breathing","is_correct":false},{"id":"b","text":"Water Breathing","is_correct":false},{"id":"c","text":"Flame Breathing","is_correct":false},{"id":"d","text":"Sun Breathing","is_correct":true}],"explanation":"Yoriichi Tsugikuni created Sun Breathing; Tanjiro knows its dances as the Hinokami Kagura."},{"id":"q6","question":"Zenitsu mastered only which form of Thunder Breathing?","options":[{"id":"a","text":"The first form","is_correct":true},{"id":"b","text":"The second form","is_correct":false},{"id":"c","text":"The third form","is_correct":false},{"id":"d","text":"The sixth form","is_correct":false}],"explanation":"He only ever learned the first form, Thunderclap and Flash, but polished it to perfection."},{"id":"q7","question":"Which flower produces a poison lethal to demons?","options":[{"id":"a","text":"Cherry blossom","is_correct":false},{"id":"b","text":"Wisteria","is_correct":true},{"id":"c","text":"Camellia","is_correct":false},{"id":"d","text":"Lotus","is_correct":false}],"explanation":"Wisteria repels and poisons demons; the Insect Hashira Shinobu Kocho uses it in her attacks."},{"id":"q8","question":"In which year did the Mugen Train movie premiere?","options":[{"id":"a","text":"2018","is_correct":false},{"id":"b","text":"2019","is_correct":false},{"id":"c","text":"2022","is_correct":false},{"id":"d","text":"2020","is_correct":true}],"explanation":"It premiered in October 2020 and became the highest-grossing anime film of all time."}]'::jsonb,
  null,
  array['demon slayer', 'kimetsu no yaiba', 'anime', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
