values (
  'es-trivia-demon-slayer',
  'Trivia de Demon Slayer: respiraciones, demonios y pilares',
  'Demon Slayer: ocho preguntas sobre el viaje de Tanjiro, las respiraciones, los pilares y los demonios de Muzan Kibutsuji.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'anime-manga'),
  '[{"id":"q1","question":"¿Quién convirtió a Nezuko, la hermana de Tanjiro, en demonio?","options":[{"id":"a","text":"Akaza","is_correct":false},{"id":"b","text":"Muzan Kibutsuji","is_correct":true},{"id":"c","text":"Rui","is_correct":false},{"id":"d","text":"Doma","is_correct":false}],"explanation":"Muzan, el primer demonio, atacó a la familia Kamado y transformó a Nezuko; es el villano principal de la serie."},{"id":"q2","question":"¿Qué estilo de respiración aprende Tanjiro primero?","options":[{"id":"a","text":"La respiración de trueno","is_correct":false},{"id":"b","text":"La respiración de llama","is_correct":false},{"id":"c","text":"La respiración de viento","is_correct":false},{"id":"d","text":"La respiración de agua","is_correct":true}],"explanation":"La aprende con Sakonji Urokodaki; la Danza del Dios del Fuego (respiración solar) llega después."},{"id":"q3","question":"¿De qué es pilar Giyu Tomioka?","options":[{"id":"a","text":"Del agua","is_correct":true},{"id":"b","text":"De la llama","is_correct":false},{"id":"c","text":"De la niebla","is_correct":false},{"id":"d","text":"De la serpiente","is_correct":false}],"explanation":"Giyu es el Pilar del Agua y quien envía a Tanjiro a entrenar con Urokodaki."},{"id":"q4","question":"¿Qué demonio mata a Kyojuro Rengoku en el Tren Infinito?","options":[{"id":"a","text":"Enmu","is_correct":false},{"id":"b","text":"Gyutaro","is_correct":false},{"id":"c","text":"Akaza","is_correct":true},{"id":"d","text":"Doma","is_correct":false}],"explanation":"Enmu cae en el tren, pero es Akaza, la Tercera Luna Superior, quien mata al Pilar de la Llama."},{"id":"q5","question":"¿De qué respiración derivan todas las demás?","options":[{"id":"a","text":"La respiración lunar","is_correct":false},{"id":"b","text":"La respiración de agua","is_correct":false},{"id":"c","text":"La respiración de llama","is_correct":false},{"id":"d","text":"La respiración solar","is_correct":true}],"explanation":"Yoriichi Tsugikuni creó la respiración solar; Tanjiro conoce sus danzas como la Danza del Dios del Fuego."},{"id":"q6","question":"¿Qué postura de la respiración de trueno domina Zenitsu?","options":[{"id":"a","text":"La primera postura","is_correct":true},{"id":"b","text":"La segunda postura","is_correct":false},{"id":"c","text":"La tercera postura","is_correct":false},{"id":"d","text":"La sexta postura","is_correct":false}],"explanation":"Solo aprendió la primera postura, el destello del trueno, pero la perfeccionó hasta el extremo."},{"id":"q7","question":"¿Qué flor produce un veneno mortal para los demonios?","options":[{"id":"a","text":"El cerezo","is_correct":false},{"id":"b","text":"La glicinia","is_correct":true},{"id":"c","text":"La camelia","is_correct":false},{"id":"d","text":"El loto","is_correct":false}],"explanation":"La glicinia repele y envenena a los demonios; Shinobu Kocho, el Pilar del Insecto, la usa en sus ataques."},{"id":"q8","question":"¿En qué año se estrenó la película Tren infinito?","options":[{"id":"a","text":"2018","is_correct":false},{"id":"b","text":"2019","is_correct":false},{"id":"c","text":"2022","is_correct":false},{"id":"d","text":"2020","is_correct":true}],"explanation":"Se estrenó en octubre de 2020 y se convirtió en la película de anime más taquillera de la historia."}]'::jsonb,
  null,
  array['demon slayer', 'kimetsu no yaiba', 'anime', 'trivia']::text[],
