insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-hunter-x-hunter-trivia',
  'Hunter x Hunter Trivia: Nen, the Exam and Chimera Ants',
  'Hunter x Hunter: eight questions about Gon, the Nen system, the Hunter Exam and the Yorknew and Chimera Ant arcs.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'anime-manga'),
  '[{"id":"q1","question":"Who is Gon searching for when he decides to become a Hunter?","options":[{"id":"a","text":"His mother","is_correct":false},{"id":"b","text":"His father, Ging","is_correct":true},{"id":"c","text":"His mentor Kite","is_correct":false},{"id":"d","text":"His older brother","is_correct":false}],"explanation":"Ging Freecss is a legendary Hunter who left Gon as a child; finding him is Gon''s goal."},{"id":"q2","question":"What is Killua''s family, the Zoldycks, famous for?","options":[{"id":"a","text":"Being Nen teachers","is_correct":false},{"id":"b","text":"Serving as butlers to the Hunter Association","is_correct":false},{"id":"c","text":"Being a family of assassins","is_correct":true},{"id":"d","text":"Being a clan of thieves","is_correct":false}],"explanation":"The Zoldycks are the world''s most famous assassin family, and Killua was raised as their heir."},{"id":"q3","question":"Which of these is NOT one of the six Nen categories?","options":[{"id":"a","text":"Enhancer","is_correct":false},{"id":"b","text":"Illusion","is_correct":true},{"id":"c","text":"Transmuter","is_correct":false},{"id":"d","text":"Specialist","is_correct":false}],"explanation":"The six categories are Enhancer, Transmuter, Conjurer, Emitter, Manipulator and Specialist."},{"id":"q4","question":"What is Hisoka''s Nen type?","options":[{"id":"a","text":"Enhancer","is_correct":false},{"id":"b","text":"Specialist","is_correct":false},{"id":"c","text":"Conjurer","is_correct":false},{"id":"d","text":"Transmuter","is_correct":true}],"explanation":"His Bungee Gum gives his aura the properties of both rubber and gum — pure transmutation."},{"id":"q5","question":"What is the name of the Chimera Ant King?","options":[{"id":"a","text":"Meruem","is_correct":true},{"id":"b","text":"Netero","is_correct":false},{"id":"c","text":"Neferpitou","is_correct":false},{"id":"d","text":"Youpi","is_correct":false}],"explanation":"Meruem is the King who defeats Netero, the Hunter Association chairman, who dies in their fight."},{"id":"q6","question":"Which group does Kurapika hunt?","options":[{"id":"a","text":"The Zoldyck family","is_correct":false},{"id":"b","text":"The Phantom Troupe","is_correct":true},{"id":"c","text":"The Chimera Ants","is_correct":false},{"id":"d","text":"The Hunter Association","is_correct":false}],"explanation":"The Phantom Troupe massacred the Kurta clan to steal their scarlet eyes, and Kurapika seeks revenge."},{"id":"q7","question":"Who created the Hunter x Hunter manga?","options":[{"id":"a","text":"Akira Toriyama","is_correct":false},{"id":"b","text":"Eiichiro Oda","is_correct":false},{"id":"c","text":"Masashi Kishimoto","is_correct":false},{"id":"d","text":"Yoshihiro Togashi","is_correct":true}],"explanation":"Togashi, also the author of Yu Yu Hakusho, has published Hunter x Hunter since 1998."},{"id":"q8","question":"Which studio animated the 2011 series?","options":[{"id":"a","text":"Madhouse","is_correct":true},{"id":"b","text":"Toei Animation","is_correct":false},{"id":"c","text":"Studio Pierrot","is_correct":false},{"id":"d","text":"Bones","is_correct":false}],"explanation":"Madhouse produced the 2011 version, which ran for 148 episodes until 2014."}]'::jsonb,
  null,
  array['hunter x hunter', 'anime', 'manga', 'nen', 'trivia']::text[],
  3,
  'published',
