  (select id from public.categories where slug = 'anime-manga'),
  '[{"id":"q1","question":"Which constellation does Seiya''s Cloth belong to?","options":[{"id":"a","text":"Dragon","is_correct":false},{"id":"b","text":"Phoenix","is_correct":false},{"id":"c","text":"Pegasus","is_correct":true},{"id":"d","text":"Cygnus","is_correct":false}],"explanation":"Seiya is the Pegasus Bronze Saint and the protagonist of the series."},{"id":"q2","question":"As whom does the goddess Athena reincarnate in the series?","options":[{"id":"a","text":"Saori Kido","is_correct":true},{"id":"b","text":"Marin","is_correct":false},{"id":"c","text":"Seika","is_correct":false},{"id":"d","text":"Shunrei","is_correct":false}],"explanation":"Saori Kido is Athena''s human reincarnation, the goddess the Saints swear to protect."},{"id":"q3","question":"How many Gold Saints guard the twelve houses of the Sanctuary?","options":[{"id":"a","text":"7","is_correct":false},{"id":"b","text":"12","is_correct":true},{"id":"c","text":"24","is_correct":false},{"id":"d","text":"88","is_correct":false}],"explanation":"There is one Gold Saint per zodiac sign; the 88 figure is the total number of constellations and Saints."},{"id":"q4","question":"Ikki, the Phoenix Saint, is the older brother of whom?","options":[{"id":"a","text":"Seiya","is_correct":false},{"id":"b","text":"Shiryu","is_correct":false},{"id":"c","text":"Hyoga","is_correct":false},{"id":"d","text":"Shun","is_correct":true}],"explanation":"Ikki is the older brother of Shun, the Andromeda Saint, whom he protects in his own way."},{"id":"q5","question":"What is the order of the Cloths from lowest to highest rank?","options":[{"id":"a","text":"Silver, Bronze, Gold","is_correct":false},{"id":"b","text":"Bronze, Silver, Gold","is_correct":true},{"id":"c","text":"Bronze, Gold, Silver","is_correct":false},{"id":"d","text":"Gold, Silver, Bronze","is_correct":false}],"explanation":"Cloths are divided into Bronze, Silver and Gold; the Gold ones are the most powerful."},{"id":"q6","question":"Who is the evil Pope revealed to be in the Sanctuary saga?","options":[{"id":"a","text":"Aries Mu","is_correct":false},{"id":"b","text":"Leo Aiolia","is_correct":false},{"id":"c","text":"Gemini Saga","is_correct":true},{"id":"d","text":"Aquarius Camus","is_correct":false}],"explanation":"Saga''s evil side murdered the true Pope and ruled the Sanctuary under his mask."},{"id":"q7","question":"Whose body does Poseidon take as his host in the second saga?","options":[{"id":"a","text":"Kanon","is_correct":false},{"id":"b","text":"Sorrento","is_correct":false},{"id":"c","text":"Ikki","is_correct":false},{"id":"d","text":"Julian Solo","is_correct":true}],"explanation":"Poseidon takes Julian Solo as his host, while Sea Dragon Kanon secretly pulls the strings."},{"id":"q8","question":"Who created Saint Seiya?","options":[{"id":"a","text":"Yoshihiro Togashi","is_correct":false},{"id":"b","text":"Akira Toriyama","is_correct":false},{"id":"c","text":"Go Nagai","is_correct":false},{"id":"d","text":"Masami Kurumada","is_correct":true}],"explanation":"Kurumada began publishing the manga in 1986, the same year Toei premiered the anime."}]'::jsonb,
