   is_featured, is_ai_generated, published_at)
values (
  'en-dragon-ball-z-sagas-trivia',
  'Dragon Ball Z Sagas Trivia: Saiyans, Frieza, Cell and Buu',
  'Dragon Ball Z: eight questions about its four great sagas — Saiyan, Frieza, Cell and Majin Buu — and the transformations they unleashed.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'anime-manga'),
  '[{"id":"q1","question":"What is Raditz to Goku?","options":[{"id":"a","text":"His cousin","is_correct":false},{"id":"b","text":"His father","is_correct":false},{"id":"c","text":"A rival from another planet","is_correct":false},{"id":"d","text":"His brother","is_correct":true}],"explanation":"Raditz is Goku''s older brother and the one who reveals his Saiyan origin and birth name, Kakarot."},{"id":"q2","question":"Whom is Goku fighting when he first turns Super Saiyan?","options":[{"id":"a","text":"Vegeta","is_correct":false},{"id":"b","text":"Frieza","is_correct":true},{"id":"c","text":"Cell","is_correct":false},{"id":"d","text":"Majin Buu","is_correct":false}],"explanation":"Krillin''s death at Frieza''s hands on Namek triggers Goku''s first transformation."},{"id":"q3","question":"Who first transforms into Super Saiyan 2 during the Cell Games?","options":[{"id":"a","text":"Goku","is_correct":false},{"id":"b","text":"Vegeta","is_correct":false},{"id":"c","text":"Trunks","is_correct":false},{"id":"d","text":"Gohan","is_correct":true}],"explanation":"Gohan unleashes Super Saiyan 2 after Android 16''s death and goes on to defeat Cell."},{"id":"q4","question":"How do Goku and Vegeta fuse to create Vegito?","options":[{"id":"a","text":"With the Fusion Dance","is_correct":false},{"id":"b","text":"With the Potara earrings","is_correct":true},{"id":"c","text":"With a wish to Shenron","is_correct":false},{"id":"d","text":"Inside the Hyperbolic Time Chamber","is_correct":false}],"explanation":"The Supreme Kai''s Potara earrings create Vegito; the Fusion Dance creates Gogeta instead."},{"id":"q5","question":"Which technique finally destroys Majin Buu?","options":[{"id":"a","text":"The Kamehameha","is_correct":false},{"id":"b","text":"The Final Flash","is_correct":false},{"id":"c","text":"The Spirit Bomb","is_correct":true},{"id":"d","text":"The Special Beam Cannon","is_correct":false}],"explanation":"A Spirit Bomb fed by the energy of the whole Earth, gathered thanks to Mr. Satan, destroys Kid Buu."},{"id":"q6","question":"Who kills Frieza when he returns to Earth?","options":[{"id":"a","text":"Goku","is_correct":false},{"id":"b","text":"Vegeta","is_correct":false},{"id":"c","text":"Piccolo","is_correct":false},{"id":"d","text":"Future Trunks","is_correct":true}],"explanation":"Future Trunks slices the rebuilt Mecha Frieza in two in his very first appearance."},{"id":"q7","question":"In which saga does Vegeta first arrive on Earth?","options":[{"id":"a","text":"The Saiyan saga","is_correct":true},{"id":"b","text":"The Frieza saga","is_correct":false},{"id":"c","text":"The Cell saga","is_correct":false},{"id":"d","text":"The Buu saga","is_correct":false}],"explanation":"Vegeta arrives with Nappa at the start of Dragon Ball Z, after Raditz''s death."},{"id":"q8","question":"In which year did Dragon Ball Z begin airing in Japan?","options":[{"id":"a","text":"1984","is_correct":false},{"id":"b","text":"1991","is_correct":false},{"id":"c","text":"1996","is_correct":false},{"id":"d","text":"1989","is_correct":true}],"explanation":"It aired from 1989 to 1996, picking up the story where Dragon Ball left off."}]'::jsonb,
  null,
  array['dragon ball z', 'dragon ball', 'goku', 'anime', 'trivia']::text[],
  3,
