values (
  'es-trivia-sagas-dragon-ball-z',
  'Trivia de Dragon Ball Z: sagas Saiyajin, Freezer, Cell y Buu',
  'Dragon Ball Z: ocho preguntas sobre sus cuatro grandes sagas — saiyajin, Freezer, Cell y Majin Buu — y las transformaciones que marcaron cada una.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'anime-manga'),
  '[{"id":"q1","question":"¿Qué es Raditz para Goku?","options":[{"id":"a","text":"Su primo","is_correct":false},{"id":"b","text":"Su padre","is_correct":false},{"id":"c","text":"Un rival de otro planeta","is_correct":false},{"id":"d","text":"Su hermano","is_correct":true}],"explanation":"Raditz es el hermano mayor de Goku y quien revela su origen saiyajin y su nombre de nacimiento, Kakarot."},{"id":"q2","question":"¿Contra quién se transforma Goku en super saiyajin por primera vez?","options":[{"id":"a","text":"Vegeta","is_correct":false},{"id":"b","text":"Freezer","is_correct":true},{"id":"c","text":"Cell","is_correct":false},{"id":"d","text":"Majin Buu","is_correct":false}],"explanation":"La muerte de Krilin a manos de Freezer en Namek desata la primera transformación de Goku."},{"id":"q3","question":"¿Quién se transforma en super saiyajin 2 por primera vez en los Juegos de Cell?","options":[{"id":"a","text":"Goku","is_correct":false},{"id":"b","text":"Vegeta","is_correct":false},{"id":"c","text":"Trunks","is_correct":false},{"id":"d","text":"Gohan","is_correct":true}],"explanation":"Gohan desata el super saiyajin 2 tras la muerte de Androide 16 y termina derrotando a Cell."},{"id":"q4","question":"¿Cómo se fusionan Goku y Vegeta para crear a Vegetto?","options":[{"id":"a","text":"Con la danza de la fusión","is_correct":false},{"id":"b","text":"Con los aretes Pothala","is_correct":true},{"id":"c","text":"Con un deseo a Shenlong","is_correct":false},{"id":"d","text":"Dentro de la habitación del tiempo","is_correct":false}],"explanation":"Los aretes Pothala del Supremo Kaio crean a Vegetto; la danza de la fusión crea a Gogeta."},{"id":"q5","question":"¿Con qué técnica destruyen a Majin Buu al final?","options":[{"id":"a","text":"El Kamehameha","is_correct":false},{"id":"b","text":"El Destello Final","is_correct":false},{"id":"c","text":"La Genkidama","is_correct":true},{"id":"d","text":"El Makankosappo","is_correct":false}],"explanation":"Una Genkidama alimentada por la energía de toda la Tierra, reunida gracias a Mr. Satán, destruye a Kid Buu."},{"id":"q6","question":"¿Quién mata a Freezer cuando regresa a la Tierra?","options":[{"id":"a","text":"Goku","is_correct":false},{"id":"b","text":"Vegeta","is_correct":false},{"id":"c","text":"Piccoro","is_correct":false},{"id":"d","text":"Trunks del futuro","is_correct":true}],"explanation":"Trunks del futuro corta en dos al Freezer mecánico en su primera aparición en la serie."},{"id":"q7","question":"¿En qué saga llega Vegeta por primera vez a la Tierra?","options":[{"id":"a","text":"En la saga saiyajin","is_correct":true},{"id":"b","text":"En la saga de Freezer","is_correct":false},{"id":"c","text":"En la saga de Cell","is_correct":false},{"id":"d","text":"En la saga de Buu","is_correct":false}],"explanation":"Vegeta llega con Nappa al inicio de Dragon Ball Z, tras la muerte de Raditz."},{"id":"q8","question":"¿En qué año comenzó a emitirse Dragon Ball Z en Japón?","options":[{"id":"a","text":"1984","is_correct":false},{"id":"b","text":"1991","is_correct":false},{"id":"c","text":"1996","is_correct":false},{"id":"d","text":"1989","is_correct":true}],"explanation":"Se emitió de 1989 a 1996, continuando la historia donde la había dejado Dragon Ball."}]'::jsonb,
  null,
  array['dragon ball z', 'dragon ball', 'goku', 'anime', 'trivia']::text[],
